-- Harvex database schema
-- Run this in: Supabase Dashboard → SQL Editor → New Query → Run
-- Tables use UUID primary keys generated by Postgres.
-- Steps 21 & 22 additions are marked with [Step 21] / [Step 22].

-- ── [Step 21] Profiles ───────────────────────────────────────────────────────
-- One row per auth.users entry. Created by the backend on first login.
-- role is set once by the user and cannot be changed via the API.
CREATE TABLE IF NOT EXISTS profiles (
    id          UUID PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE,
    role        TEXT    NOT NULL CHECK (role IN ('farmer', 'buyer')),
    full_name   TEXT,
    phone       TEXT,
    state       TEXT,
    district    TEXT,
    created_at  TIMESTAMPTZ DEFAULT now()
);

-- [Step 24] Add profile fields if table already exists (safe to re-run)
ALTER TABLE profiles ADD COLUMN IF NOT EXISTS phone    TEXT;
ALTER TABLE profiles ADD COLUMN IF NOT EXISTS state    TEXT;
ALTER TABLE profiles ADD COLUMN IF NOT EXISTS district TEXT;

-- 1. Farmer inputs ─────────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS farmer_inputs (
    id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    -- [Step 21] link each submission to the authenticated farmer
    user_id         UUID    REFERENCES auth.users(id) ON DELETE SET NULL,
    crop            TEXT    NOT NULL,
    quantity_kg     NUMERIC NOT NULL,
    quality         TEXT    NOT NULL,   -- 'Premium' | 'Standard' | 'Low'
    farmer_location TEXT    NOT NULL,
    harvest_date    TEXT    NOT NULL,
    shelf_life_days INTEGER NOT NULL,
    created_at      TIMESTAMPTZ DEFAULT now()
);

-- 2. Decision results ──────────────────────────────────────────────────────────
-- One row per plan per submission.
-- plan_name values: 'optimize_recommended', 'plan_a', 'plan_b', 'plan_c'
CREATE TABLE IF NOT EXISTS decision_results (
    id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    farmer_input_id     UUID    NOT NULL REFERENCES farmer_inputs(id) ON DELETE CASCADE,
    plan_name           TEXT    NOT NULL,
    total_allocated_kg  NUMERIC NOT NULL,
    gross_revenue       NUMERIC NOT NULL,
    transport_cost      NUMERIC NOT NULL,
    spoilage_loss       NUMERIC NOT NULL,
    expected_net_value  NUMERIC NOT NULL,
    created_at          TIMESTAMPTZ DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_decision_results_input
    ON decision_results(farmer_input_id);

-- 3. Allocations ───────────────────────────────────────────────────────────────
-- One row per buyer/market per plan.
CREATE TABLE IF NOT EXISTS allocations (
    id                      UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    decision_result_id      UUID    NOT NULL REFERENCES decision_results(id) ON DELETE CASCADE,
    buyer_name              TEXT    NOT NULL,
    allocated_quantity_kg   NUMERIC NOT NULL,
    selling_price_per_kg    NUMERIC NOT NULL,
    gross_revenue           NUMERIC NOT NULL,
    transport_cost          NUMERIC NOT NULL,
    spoilage_loss           NUMERIC NOT NULL,
    expected_net_value      NUMERIC NOT NULL
);

CREATE INDEX IF NOT EXISTS idx_allocations_result
    ON allocations(decision_result_id);

-- ── [Step 22] Row Level Security ─────────────────────────────────────────────

-- Enable RLS on all four tables
ALTER TABLE profiles         ENABLE ROW LEVEL SECURITY;
ALTER TABLE farmer_inputs    ENABLE ROW LEVEL SECURITY;
ALTER TABLE decision_results ENABLE ROW LEVEL SECURITY;
ALTER TABLE allocations      ENABLE ROW LEVEL SECURITY;

-- ── profiles policies ─────────────────────────────────────────────────────────

-- Users can read only their own profile
DROP POLICY IF EXISTS "profiles: owner select" ON profiles;
CREATE POLICY "profiles: owner select"
    ON profiles FOR SELECT
    USING (auth.uid() = id);

-- Users can insert their own profile (role is set on creation, not changed)
DROP POLICY IF EXISTS "profiles: owner insert" ON profiles;
CREATE POLICY "profiles: owner insert"
    ON profiles FOR INSERT
    WITH CHECK (auth.uid() = id);

-- Users cannot update their own role (no UPDATE policy → updates blocked)
-- Backend service-role key bypasses RLS for administrative operations.

-- RLS does not replace PostgreSQL table privileges. The API uses the
-- backend-only service_role client to look up, create, and update profiles.
-- Authenticated users retain only the operations allowed by the owner policies;
-- anonymous users receive no profile-table access.
REVOKE ALL ON TABLE profiles FROM anon;
GRANT SELECT, INSERT ON TABLE profiles TO authenticated;
GRANT SELECT, INSERT, UPDATE ON TABLE profiles TO service_role;

-- ── farmer_inputs policies ────────────────────────────────────────────────────

-- A farmer can read their own submissions
DROP POLICY IF EXISTS "farmer_inputs: farmer select" ON farmer_inputs;
CREATE POLICY "farmer_inputs: farmer select"
    ON farmer_inputs FOR SELECT
    USING (
        auth.uid() = user_id
        AND EXISTS (
            SELECT 1 FROM profiles
            WHERE profiles.id = auth.uid()
              AND profiles.role = 'farmer'
        )
    );

-- A farmer can insert only their own submissions
DROP POLICY IF EXISTS "farmer_inputs: farmer insert" ON farmer_inputs;
CREATE POLICY "farmer_inputs: farmer insert"
    ON farmer_inputs FOR INSERT
    WITH CHECK (
        auth.uid() = user_id
        AND EXISTS (
            SELECT 1 FROM profiles
            WHERE profiles.id = auth.uid()
              AND profiles.role = 'farmer'
        )
    );

-- ── decision_results policies ─────────────────────────────────────────────────

-- A farmer can read results for their own farmer_inputs
DROP POLICY IF EXISTS "decision_results: farmer select" ON decision_results;
CREATE POLICY "decision_results: farmer select"
    ON decision_results FOR SELECT
    USING (
        EXISTS (
            SELECT 1 FROM farmer_inputs fi
            WHERE fi.id = decision_results.farmer_input_id
              AND fi.user_id = auth.uid()
        )
        AND EXISTS (
            SELECT 1 FROM profiles
            WHERE profiles.id = auth.uid()
              AND profiles.role = 'farmer'
        )
    );

-- ── allocations policies ──────────────────────────────────────────────────────

-- A farmer can read allocations for their own decision results
DROP POLICY IF EXISTS "allocations: farmer select" ON allocations;
CREATE POLICY "allocations: farmer select"
    ON allocations FOR SELECT
    USING (
        EXISTS (
            SELECT 1
            FROM decision_results dr
            JOIN farmer_inputs fi ON fi.id = dr.farmer_input_id
            WHERE dr.id = allocations.decision_result_id
              AND fi.user_id = auth.uid()
        )
        AND EXISTS (
            SELECT 1 FROM profiles
            WHERE profiles.id = auth.uid()
              AND profiles.role = 'farmer'
        )
    );

-- ── [Step 23] Farmer consent ─────────────────────────────────────────────────
-- One row per farmer. Re-consent creates a new row; previous rows are kept.
CREATE TABLE IF NOT EXISTS farmer_consents (
    id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id      UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    consented_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    version      TEXT NOT NULL DEFAULT '1.0'  -- bump when terms materially change
);

CREATE INDEX IF NOT EXISTS idx_farmer_consents_user
    ON farmer_consents(user_id);

ALTER TABLE farmer_consents ENABLE ROW LEVEL SECURITY;

-- Farmer can read their own consent records
DROP POLICY IF EXISTS "farmer_consents: owner select" ON farmer_consents;
CREATE POLICY "farmer_consents: owner select"
    ON farmer_consents FOR SELECT
    USING (auth.uid() = user_id);

-- Farmer can insert their own consent
DROP POLICY IF EXISTS "farmer_consents: owner insert" ON farmer_consents;
CREATE POLICY "farmer_consents: owner insert"
    ON farmer_consents FOR INSERT
    WITH CHECK (auth.uid() = user_id);

-- RLS policies decide which rows may be accessed, but PostgreSQL table
-- privileges are still required.  Keep anonymous users out, allow signed-in
-- farmers through the owner policies above, and allow the backend service-role
-- client to perform its consent lookup/insert without exposing that key.
REVOKE ALL ON TABLE farmer_consents FROM anon;
GRANT SELECT, INSERT ON TABLE farmer_consents TO authenticated;
GRANT SELECT, INSERT ON TABLE farmer_consents TO service_role;

-- ── [Step 28] Buyer-specific profile columns ─────────────────────────────────
ALTER TABLE profiles ADD COLUMN IF NOT EXISTS company_name TEXT;
ALTER TABLE profiles ADD COLUMN IF NOT EXISTS business_type TEXT;

-- ── [Step 29 / 31] Buyer requirements ────────────────────────────────────────
-- One row per procurement requirement posted by a buyer.
CREATE TABLE IF NOT EXISTS buyer_requirements (
    id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id           UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,
    crop              TEXT NOT NULL,
    quantity_kg       NUMERIC NOT NULL CHECK (quantity_kg > 0),
    quality           TEXT NOT NULL CHECK (quality IN ('Premium', 'Standard', 'Low', 'Any')),
    delivery_state    TEXT,
    delivery_district TEXT,
    budget_per_kg     NUMERIC CHECK (budget_per_kg IS NULL OR budget_per_kg > 0),
    needed_by         TEXT,
    notes             TEXT,
    is_active         BOOLEAN NOT NULL DEFAULT TRUE,
    created_at        TIMESTAMPTZ DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_buyer_requirements_user
    ON buyer_requirements(user_id);

ALTER TABLE buyer_requirements ENABLE ROW LEVEL SECURITY;

-- A buyer can read only their own requirements
DROP POLICY IF EXISTS "buyer_requirements: owner select" ON buyer_requirements;
CREATE POLICY "buyer_requirements: owner select"
    ON buyer_requirements FOR SELECT
    USING (
        auth.uid() = user_id
        AND EXISTS (
            SELECT 1 FROM profiles
            WHERE profiles.id = auth.uid()
              AND profiles.role = 'buyer'
        )
    );

-- A buyer can create their own requirements
DROP POLICY IF EXISTS "buyer_requirements: owner insert" ON buyer_requirements;
CREATE POLICY "buyer_requirements: owner insert"
    ON buyer_requirements FOR INSERT
    WITH CHECK (
        auth.uid() = user_id
        AND EXISTS (
            SELECT 1 FROM profiles
            WHERE profiles.id = auth.uid()
              AND profiles.role = 'buyer'
        )
    );

-- A buyer can update their own requirements
DROP POLICY IF EXISTS "buyer_requirements: owner update" ON buyer_requirements;
CREATE POLICY "buyer_requirements: owner update"
    ON buyer_requirements FOR UPDATE
    USING (
        auth.uid() = user_id
        AND EXISTS (
            SELECT 1 FROM profiles
            WHERE profiles.id = auth.uid()
              AND profiles.role = 'buyer'
        )
    );

-- A buyer can delete their own requirements
DROP POLICY IF EXISTS "buyer_requirements: owner delete" ON buyer_requirements;
CREATE POLICY "buyer_requirements: owner delete"
    ON buyer_requirements FOR DELETE
    USING (
        auth.uid() = user_id
        AND EXISTS (
            SELECT 1 FROM profiles
            WHERE profiles.id = auth.uid()
              AND profiles.role = 'buyer'
        )
    );

-- ── Anonymous access is blocked by default ────────────────────────────────────
-- No policies grant access to anon role, so anonymous requests are denied
-- on all tables once RLS is enabled.

-- Note: the backend uses the service_role key which bypasses RLS, so
-- server-side inserts (via /api/submission) continue to work without
-- needing the authenticated user's JWT on the backend.
